import { Toggle as BaseToggle } from '@base-ui/react/toggle';
import { ToggleGroup as BaseToggleGroup } from '@base-ui/react/toggle-group';
import { useRender } from '@base-ui/react/use-render';
import { Check } from 'lucide-react';
import { createContext, useContext, type ReactNode, type Ref } from 'react';
import { cn } from '../../utils/cn';
import {
  toggleGroupVariants,
  toggleVariants,
  type ToggleGroupVariantProps,
  type ToggleVariantProps,
} from './toggle-group.variants';

type GroupStyle = { variant: 'segmented' | 'joined' | 'chip'; size: 'auto' | 'sm' | 'md' };
const GroupStyleContext = createContext<GroupStyle | null>(null);

export interface ToggleProps extends Omit<BaseToggle.Props, 'className'>, Omit<ToggleVariantProps, 'variant'> {
  className?: string;
  ref?: Ref<HTMLButtonElement>;
  children?: ReactNode;
  /** Trailing count, included in the accessible name. */
  count?: ReactNode;
}

/**
 * Two-state (pressed) button. Standalone: `pressed` / `defaultPressed` / `onPressedChange`.
 * Inside a ToggleGroup: give it a `value`; it inherits the group's look. Icon-only toggles
 * need `aria-label` (set `iconOnly`).
 */
export function Toggle({ size, iconOnly, className, render, children, count, type = 'button', ...props }: ToggleProps) {
  const group = useContext(GroupStyleContext);
  return (
    <BaseToggle
      type={type}
      className={cn(
        toggleVariants({ variant: group?.variant ?? 'standalone', size: size ?? group?.size ?? 'auto', iconOnly }),
        className,
      )}
      {...props}
      children={
        count == null ? (
          children
        ) : (
          <>
            {children} <span className="font-mono tabular-nums text-[11px]">{count}</span>
          </>
        )
      }
      render={
        group?.variant === 'chip'
          ? (elementProps, state) => <ChipButton elementProps={elementProps} state={state} render={render} />
          : render
      }
    />
  );
}

export interface ToggleGroupProps extends Omit<BaseToggleGroup.Props<string>, 'className'>, ToggleGroupVariantProps {
  className?: string;
  ref?: Ref<HTMLDivElement>;
  /** Item size, passed down to every Toggle. `auto` (default) follows the density. */
  size?: 'auto' | 'sm' | 'md';
  /**
   * Keep at least one item pressed: a change that would leave the value empty is ignored
   * (the pressed item stays pressed and `onValueChange` is not called). Works in single and
   * `multiple` mode, controlled or not. An uncontrolled `defaultValue` is read once. A group
   * that starts empty stays empty until the first press. Default `false`.
   */
  disallowEmptySelection?: boolean;
}

/**
 * A set of Toggles with shared state: segmented control (`multiple={false}`, the default)
 * or multi-select toolbar (`multiple`). Arrow keys move focus; Space/Enter toggles.
 * Give it an `aria-label`. `disallowEmptySelection` keeps one item pressed.
 */
export function ToggleGroup({
  variant = 'segmented',
  size = 'auto',
  className,
  disallowEmptySelection = false,
  onValueChange,
  ...props
}: ToggleGroupProps) {
  const handleValueChange: BaseToggleGroup.Props<string>['onValueChange'] = (next, eventDetails) => {
    if (disallowEmptySelection && next.length === 0) {
      eventDetails.cancel();
      return;
    }
    onValueChange?.(next, eventDetails);
  };
  return (
    <GroupStyleContext.Provider value={{ variant: variant ?? 'segmented', size }}>
      <BaseToggleGroup
        className={cn(toggleGroupVariants({ variant }), className)}
        onValueChange={handleValueChange}
        {...props}
      />
    </GroupStyleContext.Provider>
  );
}

/** Uses Base UI's pressed state without duplicating its selection or focus logic. */
function ChipButton({
  elementProps,
  state,
  render,
}: {
  elementProps: useRender.ElementProps<'button'>;
  state: BaseToggle.State;
  render: BaseToggle.Props['render'];
}) {
  return useRender<{ pressed: boolean; disabled: boolean }, HTMLButtonElement>({
    defaultTagName: 'button',
    render,
    props: {
      ...elementProps,
      children: (
        <>
          {state.pressed && <Check size={14} aria-hidden />}
          {elementProps.children}
        </>
      ),
    },
    state,
  });
}

export { Toggle, ToggleGroup, type ToggleProps, type ToggleGroupProps } from './ToggleGroup';
export { toggleGroupVariants, toggleVariants } from './toggle-group.variants';
export { doc as toggleGroupDoc } from './ToggleGroup.doc';

import { tv, type VariantProps } from '../../utils/tv';

export const toggleGroupVariants = tv({
  base: 'inline-flex data-[orientation=vertical]:flex-col data-disabled:opacity-50',
  variants: {
    variant: {
      chip: 'flex-wrap gap-1.5',
      /** Pill container; the pressed item lifts onto bg-secondary. */
      segmented: 'items-center gap-0.5 rounded-lg border border-border bg-card p-0.5 shadow-sm',
      /** Buttons sharing borders; rounding only on the container. */
      joined:
        'overflow-hidden rounded-lg border border-border bg-card shadow-sm divide-x divide-border data-[orientation=vertical]:divide-x-0 data-[orientation=vertical]:divide-y',
    },
  },
  defaultVariants: { variant: 'segmented' },
});

export const toggleVariants = tv({
  base: [
    'inline-flex shrink-0 items-center justify-center gap-2 font-medium whitespace-nowrap text-muted-foreground transition-colors select-none',
    'hover:text-foreground data-pressed:bg-secondary data-pressed:text-foreground forced-colors:data-pressed:bg-[Highlight] forced-colors:data-pressed:text-[HighlightText] forced-colors:data-pressed:[&_*]:text-[HighlightText] forced-colors:data-pressed:hover:bg-[Highlight] forced-colors:data-pressed:hover:text-[HighlightText] forced-colors:data-pressed:hover:[&_*]:text-[HighlightText]',
    'focus-visible:relative focus-visible:z-raised focus-ring',
    'data-disabled:cursor-disabled data-disabled:opacity-50 data-disabled:hover:text-muted-foreground',
  ],
  variants: {
    variant: {
      /** Standalone pressed button. */
      standalone:
        'rounded-lg border border-border bg-card shadow-sm hover:bg-secondary/50 data-pressed:border-primary/40',
      segmented: 'rounded-md data-pressed:shadow-sm',
      joined: 'hover:bg-secondary/50',
      chip: 'rounded-full border border-border bg-card px-3 hover:bg-secondary/50 data-pressed:border-primary/40 data-pressed:bg-primary/14 data-pressed:text-primary-chip-text',
    },
    size: {
      /** Follows `data-density` (comfortable = md). */
      auto: 'h-control px-4 text-[13px]',
      sm: 'h-8 px-3 text-[12.5px]',
      md: 'h-9 px-4 text-[13px]',
    },
    iconOnly: { true: 'px-0' },
  },
  compoundVariants: [
    { variant: 'chip', size: 'auto', class: 'h-control-sm px-3' },
    { variant: 'chip', size: 'sm', class: 'h-7 px-3' },
    { variant: 'chip', size: 'md', class: 'h-8 px-3' },
    { variant: 'segmented', size: 'auto', class: 'h-control-sm px-control-sm text-[12.5px]' },
    { variant: 'segmented', size: 'md', class: 'h-8 px-3 text-[12.5px]' },
    { variant: 'segmented', size: 'sm', class: 'h-7 px-2.5 text-[12px]' },
    { iconOnly: true, size: 'auto', class: 'size-control px-0' },
    { iconOnly: true, size: 'sm', class: 'size-8 px-0' },
    { iconOnly: true, size: 'md', class: 'size-9 px-0' },
    { iconOnly: true, variant: 'segmented', size: 'auto', class: 'size-control-sm' },
    { iconOnly: true, variant: 'segmented', size: 'md', class: 'size-8' },
    { iconOnly: true, variant: 'segmented', size: 'sm', class: 'size-7' },
    { iconOnly: true, variant: 'chip', size: 'auto', class: 'size-control-sm' },
    { iconOnly: true, variant: 'chip', size: 'md', class: 'size-8' },
    { iconOnly: true, variant: 'chip', size: 'sm', class: 'size-7' },
  ],
  defaultVariants: { variant: 'standalone', size: 'auto', iconOnly: false },
});

export type ToggleGroupVariantProps = VariantProps<typeof toggleGroupVariants>;
export type ToggleVariantProps = VariantProps<typeof toggleVariants>;

/**
 * Component documentation contract. Every component folder exports a `*.doc.ts`
 * with this shape; the registry build and the docs site read it.
 */
export interface ComponentDoc {
  /** Public component name, e.g. "Button". */
  name: string;
  /** Inventory group, e.g. "Actions", "Forms", "Overlays". */
  group: 'Actions' | 'Forms' | 'Overlays' | 'Navigation' | 'Display' | 'Feedback' | 'Layout' | 'Theme';
  /** Lifecycle badge. */
  status: 'stable' | 'beta' | 'experimental';
  description: string;
  /** Headless primitive it is built on, if any (e.g. "@base-ui/react/dialog"). */
  primitive?: string;
  /** JSX skeleton showing the public compound parts. */
  anatomy?: string;
  /** State attribute, styled part and product-agnostic meaning. */
  dataAttributes?: Array<[attribute: string, part: string, meaning: string]>;
  /** WAI-ARIA pattern the a11y contract test checks. */
  pattern?: string;
  /** Keyboard contract: key → behaviour. Each row is covered by a test. */
  keyboard?: Array<[key: string, behaviour: string]>;
  /** Tokens the component reads (for the theming docs). */
  tokens?: string[];
}

/**
 * Hook documentation contract. Every hook in `src/hooks/index.ts` has a `hooks/<useName>.doc.ts`
 * exporting `doc: HookDoc`; the registry build, the docs Hooks page and the coverage test read it.
 */
export interface HookDoc {
  /** Public hook name, e.g. "useClipboard". */
  name: string;
  /** Lifecycle badge. */
  status: ComponentDoc['status'];
  description: string;
  /** Call signature, e.g. "useClipboard(options?): { copy, status, copied, error, reset }". */
  signature: string;
  /**
   * What the hook returns without a DOM (server render and first hydration render). Put literal
   * values in backticks: the SSR test checks that the example's server output contains each one.
   */
  server: string;
  /** Non-hook helpers exported next to the hook that this doc covers, e.g. "readLocalStorageValue". Every `use*` hook has its own doc. */
  also?: string[];
}
